import {
  canFetchNewModelsFromProvider,
  fieldsToEncrypt,
  getSampleCustomKeyNameFor,
  type Provider,
  providerApiKeyLabel,
} from '@github-ui/copilot-byok/providers'
import {ProviderPicker} from '@github-ui/copilot-byok/providers/ProviderPicker'
import {useProviders} from '@github-ui/copilot-byok/providers/react'
import {encrypt} from '@github-ui/encryption'
import {encode} from '@github-ui/encryption/utils'
import {ResponseError} from '@github-ui/react-core/future/response-error'
import {useMutation} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {SyncIcon} from '@primer/octicons-react'
import {Banner, Dialog, FormControl, Stack, TextInput} from '@primer/react'
import {type FormEvent, type RefObject, startTransition, useCallback, useId, useMemo, useRef, useState} from 'react'
import * as z from 'zod'

import {useCurrentOrg} from '../contexts/CurrentOrgContext'
import {getErrorMessageFromResponse} from '../helpers/extract-errors'
import {type ValidationKind, validationKindFromZodError} from '../helpers/validation'
import {useAPIKey} from '../hooks/use-api-key'
import type {CreateCustomKeyMutationData, ProviderAdditionalData} from '../types'
import styles from './AddEditDialog.module.css'
import {FormValidationNode} from './FormValidationNode'
import {preprocessProviderFormPayload, providerFields, providerSchema} from './providers'

const formSchema = z.lazy(() => {
  const base = z.object({
    provider: z.string().nonempty('A provider must be selected'),
    name: z.string().nonempty('A name is required'),
    api_key: z.string().nonempty('An API key is required'),
  })

  return z.union(providerSchema.map(schema => base.extend(schema)))
})

function useCreateCustomKey({org, publicKey}: {org: string; publicKey: string}) {
  return useMutation<CreateCustomKeyMutationData, ResponseError, z.infer<typeof formSchema>>({
    async mutationFn(variables) {
      const body: Record<string, unknown> = Object.assign({}, variables)

      for (const fieldName of fieldsToEncrypt) {
        if (typeof body[fieldName] === 'string') {
          const encryptedValue = await encrypt(publicKey, body[fieldName])
          body[fieldName] = encode(encryptedValue)
        }
      }

      const r = await reactFetchJSON(`/organizations/${org}/settings/copilot/custom-models`, {
        method: 'POST',
        body,
      })
      if (!r.ok) throw new ResponseError('Failed to add API key', r)
      return r.json() as Promise<CreateCustomKeyMutationData>
    },
  })
}

export function AddKeyDialog({
  publicKey,
  anchorRef,
  onCancel,
  onSuccess,
}: {
  publicKey: string
  anchorRef?: RefObject<HTMLElement | null>
  onCancel: () => void
  onSuccess: (data: CreateCustomKeyMutationData) => void
}) {
  const id = useId()
  const nameValidationId = `name-validation-${id}`
  const nameCaptionId = `name-caption-${id}`
  const apiKeyValidationId = `api_key-validation-${id}`

  const [selectedProvider, setSelectedProvider] = useState<Provider>('openai')
  const [validation, setValidation] = useState<Record<string, ValidationKind>>()
  const [apiKey, setApiKey] = useAPIKey(publicKey)
  const [apiKeyInput, setApiKeyInput] = useState('')
  const additionalDataRef = useRef<ProviderAdditionalData>(undefined)
  const org = useCurrentOrg()
  const providers = useProviders()
  const {mutate, isPending} = useCreateCustomKey({org, publicKey})

  function onSubmitHandler(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    const formData = new FormData(event.currentTarget)
    const payload = Object.fromEntries(formData.entries()) as Record<string, unknown>
    Object.assign(payload, additionalDataRef.current)

    const {success, data, error} = formSchema.safeParse(preprocessProviderFormPayload(selectedProvider, payload))
    if (!success) {
      setValidation(validationKindFromZodError(error))
      return
    }

    startTransition(() => {
      setValidation(undefined)
      mutate(data, {
        onSuccess,
        // eslint-disable-next-line @typescript-eslint/no-misused-promises
        async onError(mutationError) {
          const message = await getErrorMessageFromResponse(mutationError)

          setValidation({
            __general: {error: message || 'An unexpected error occurred. Please try again later.'},
          })
        },
      })
    })
  }

  const ProviderFields = useMemo(() => {
    return providerFields[selectedProvider]
  }, [selectedProvider])

  const onSelectProvider = useCallback((provider: Provider) => {
    setSelectedProvider(provider)
    additionalDataRef.current = undefined
  }, [])

  const onSetAdditionalData = useCallback((data: ProviderAdditionalData) => {
    const existingValue: ProviderAdditionalData = additionalDataRef.current
    additionalDataRef.current = existingValue && data ? {...existingValue, ...data} : data
  }, [])

  const handleClose = useCallback(() => {
    onCancel()
  }, [onCancel])

  const canFetchNewModels = canFetchNewModelsFromProvider(selectedProvider) && apiKeyInput.trim().length > 0

  return (
    <Dialog
      title="Add API key"
      onClose={handleClose}
      position="right"
      width="large"
      className={styles.AddEditDialogLayout}
      returnFocusRef={anchorRef}
      footerButtons={[
        {content: 'Cancel', buttonType: 'default', onClick: onCancel},
        {
          content: 'Save',
          buttonType: 'primary',
          type: 'submit',
          form: `${id}-form`,
          loading: isPending,
          loadingAnnouncement: 'Adding custom key',
        },
      ]}
    >
      <Stack
        as="form"
        id={`${id}-form`}
        className="height-full"
        onSubmit={onSubmitHandler as unknown as React.FormEventHandler<HTMLDivElement>}
      >
        {validation?.__general && (
          <Banner role="banner" title="Error" variant="critical" hideTitle description={validation.__general.error} />
        )}

        <FormControl id={`${id}-provider`} disabled={isPending}>
          <ProviderPicker
            id={`${id}-provider`}
            providers={providers}
            selected={selectedProvider}
            onSelected={onSelectProvider}
            disabled={isPending}
          />
          <FormControl.Label>Provider</FormControl.Label>
          <input type="hidden" name="provider" value={selectedProvider} />
        </FormControl>

        <FormControl required disabled={isPending}>
          <FormControl.Label>Name</FormControl.Label>
          <TextInput
            name="name"
            data-1p-ignore
            placeholder={getSampleCustomKeyNameFor(selectedProvider)}
            className="width-full"
            aria-describedby={`${nameValidationId} ${nameCaptionId}`}
            autoComplete="off"
          />
          <FormValidationNode item={validation?.name} id={nameValidationId} />
          <FormControl.Caption id={nameCaptionId}>Models provided will be available under this key</FormControl.Caption>
        </FormControl>

        <FormControl required disabled={isPending}>
          <FormControl.Label>{providerApiKeyLabel(selectedProvider)}</FormControl.Label>
          <TextInput
            name="api_key"
            data-1p-ignore
            value={apiKeyInput}
            onChange={e => setApiKeyInput(e.currentTarget.value)}
            onBlur={e => {
              if (selectedProvider === 'azureai') {
                void setApiKey(e.currentTarget.value)
              }
            }}
            type="password"
            autoComplete="new-password"
            className="width-full"
            aria-describedby={apiKeyValidationId}
            trailingAction={
              canFetchNewModels ? (
                <TextInput.Action
                  onClick={() => setApiKey(apiKeyInput)}
                  icon={SyncIcon}
                  aria-label="Fetch new models"
                />
              ) : undefined
            }
          />
          <FormValidationNode item={validation?.api_key} id={apiKeyValidationId} />
        </FormControl>

        <ProviderFields
          apiKey={apiKey}
          publicKey={publicKey}
          validation={validation}
          setValidation={setValidation}
          isPending={isPending}
          onSetAdditionalData={onSetAdditionalData}
          org={org}
        />
      </Stack>
    </Dialog>
  )
}
